// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Unit tests for task validation and plus lists
// Flo: build Task > vali > assert null or exact reason
// I/O: Task specs > reason text or null
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const stor = @import("tk-task-stor.zig");
const tszz = std.testing; const Task = stor.Task; const Reje = stor.Reje; const vali = stor.vali; const norm = stor.norm; const chaiFind = stor.chaiFind; const idenVali = stor.idenVali; const autoRunz = stor.autoRunz;
fn testJson(allo: std.mem.Allocator, text: []const u8) std.json.Value { return std.json.parseFromSliceLeaky(std.json.Value, allo, text, .{}) catch unreachable; }
test "validate accepts a minimal cron task" { const task: Task = .{ .id = "nightly", .type = "cron", .sche = "0 2 * * *", .run = "zig build" }; try tszz.expect(vali(task) == null); }
test "validate rejects missing fields" { try tszz.expect(vali(.{ .type = "cron", .sche = "0 2 * * *", .run = "x" }) != null); try tszz.expect(vali(.{ .id = "a", .sche = "0 2 * * *", .run = "x" }) != null); try tszz.expect(vali(.{ .id = "a", .type = "cron", .sche = "0 2 * * *" }) != null); }
test "validate rejects an unknown type" { try tszz.expect(vali(.{ .id = "a", .type = "nope", .sche = "x", .run = "y" }) != null); }
test "no-sche types do not require sche" { for (stor.NONE_SCHE) |kind| { const task: Task = if (std.mem.eql(u8, kind, "chai")) .{ .id = "a", .type = kind, .ids = &.{"b"} } else .{ .id = "a", .type = kind, .run = "x" }; try tszz.expect(vali(task) == null); } }
test "chai needs ids, no run, no self or duplicate member" { const okay: Task = .{ .id = "c", .type = "chai", .ids = &.{ "a", "b" } }; try tszz.expect(vali(okay) == null); try tszz.expect(vali(.{ .id = "c", .type = "chai" }) != null); try tszz.expect(vali(.{ .id = "c", .type = "chai", .ids = &.{} }) != null); try tszz.expect(vali(.{ .id = "c", .type = "chai", .ids = &.{"a"}, .run = "x" }) != null); try tszz.expect(vali(.{ .id = "c", .type = "chai", .ids = &.{"c"} }) != null); try tszz.expect(vali(.{ .id = "c", .type = "chai", .ids = &.{ "a", "a" } }) != null); try tszz.expect(vali(.{ .id = "c", .type = "chai", .ids = &.{"a/b"} }) != null); try tszz.expect(vali(.{ .id = "a", .type = "hand", .run = "x", .ids = &.{"b"} }) != null); }
test "plus: letters and lists are accepted, anything else is refused, only a chai may carry it" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); const good = [_][]const u8{ "[\"y\",\"m\",\"d\",\"h\",[1,2,3],\"s\"]", "[[0],[0],[0],[1,1,2],[5],[0,30]]", "[]", "[\"y\",\"m\",\"d\",[23]]", "[[10],[11],[30],[23],[59],[59]]", "[\"y\",\"m\",\"d\",\"h\",\"4..12\",\"s\"]", "[\"y\",\"m\",\"d\",\"h\",[1,\"5..7\"],\"s\"]" }; for (good) |text| try tszz.expect(vali(.{ .id = "c", .type = "chai", .ids = &.{"a"}, .plus = testJson(allo, text) }) == null); const badz = [_][]const u8{ "[\"a\",\"a\",\"a\",\"a\",\"a\",\"a\",\"a\"]", "[\"yy\"]", "[\"1\"]", "[5]", "[[11]]", "[\"y\",\"m\",\"d\",[24]]", "[[1.5]]", "[[-1]]", "[[\"x\"]]", "[\"y\",\"m\",\"d\",\"h\",\"4..70\"]", "[\"y\",\"m\",\"d\",\"h\",\"9..4\"]", "{\"a\":1}" }; for (badz) |text| try tszz.expect(vali(.{ .id = "c", .type = "chai", .ids = &.{"a"}, .plus = testJson(allo, text) }) != null); try tszz.expect(vali(.{ .id = "a", .type = "hand", .run = "x", .plus = testJson(allo, "[]") }) != null); }
test "sche-requiring types reject a missing or blank sche" { try tszz.expect(vali(.{ .id = "a", .type = "cron", .run = "x" }) != null); try tszz.expect(vali(.{ .id = "a", .type = "cron", .sche = "   ", .run = "x" }) != null); }
test "id cannot escape the task-state directory" { const evil = [_][]const u8{ "../../etc/passwd", "a/b", "a\\b", "C:evil", "a*b", "a?b", "a\"b", "a<b", "a>b", "a|b", ".", ".." }; for (evil) |iden| { const task: Task = .{ .id = iden, .type = "hand", .run = "x" }; try tszz.expect(vali(task) != null); } }
test "unimplemented fields are refused, not silently ignored" { const base: Task = .{ .id = "a", .type = "hand", .run = "x" }; try tszz.expect(vali(base) == null); var guar = base; guar.guard = "1/h"; try tszz.expect(vali(guar) != null); var npdz = base; npdz.npd = 3; try tszz.expect(vali(npdz) != null); var admi = base; admi.admin = true; try tszz.expect(vali(admi) != null); var dela = base; dela.type = "boot"; dela.dela = 5; try tszz.expect(vali(dela) == null); var nolo = base; nolo.noLog = true; try tszz.expect(vali(nolo) == null); }
test "tmo and try are bounded, not free-form" { const base: Task = .{ .id = "a", .type = "hand", .run = "x" }; var okay = base; okay.tmo = 30; okay.@"try" = 3; try tszz.expect(vali(okay) == null); var zero = base; zero.tmo = 0; try tszz.expect(vali(zero) != null); var huge = base; huge.tmo = stor.MAXZ_TMOZ_SECO + 1; try tszz.expect(vali(huge) != null); var many = base; many.@"try" = stor.MAXZ_RETR + 1; try tszz.expect(vali(many) != null); var oldz = base; oldz.tmoS = stor.MAXZ_TMOZ_SECO + 1; try tszz.expect(vali(oldz) != null); oldz.tmoS = 30; oldz.retry = 2; oldz.dlyM = 4; try tszz.expect(vali(oldz) == null); }
test "loop requires kind shell" { try tszz.expect(vali(.{ .id = "a", .type = "loop", .kind = "http", .run = "x" }) != null); try tszz.expect(vali(.{ .id = "a", .type = "loop", .kind = "shell", .run = "x" }) == null); }
test "a task with the old lock key is rejected: locks live in aa-conf-main.json lock_list" { try tszz.expect(vali(.{ .id = "a", .type = "cron", .sche = "0 2 * * *", .run = "x" }) == null); try tszz.expect(vali(.{ .id = "a", .type = "cron", .sche = "0 2 * * *", .run = "x", .lock = "scra" }) != null); }
